 denied:=false; begin perform onboard_creator(a,cx,y,jsonb_build_object('agreement_reference','TEST-CONTRACT-X','signed_at',now())); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Onboarding steals a linked identity'; end if;
 insert into creator_profiles(slug,display_name,title,availability) values(gen_random_uuid()::text,'Expiry Creator','Video','AVAILABLE') returning id into cz;
 perform onboard_creator(a,cz,z,jsonb_build_object('agreement_reference','TEST-CONTRACT-Z','signed_at',now()));
 insert into services(name,slug,active) values('Team service',gen_random_uuid()::text,true) returning id into svc;
 rid:=(request_action(c,null,'create',jsonb_build_object('service_id',svc,'title','Team request','brief','Test only','idempotency_key',gen_random_uuid()))->>'id')::uuid;
