 select id into conv from conversations where request_id=rid;
 perform request_action(c,rid,'message','{"content":"Private negotiation before signing"}');
 if service_chat_scope(x,rid) is not null then raise exception 'Creator opens chat before assignment/contract';end if;
 px:=(request_commerce_action(s,rid,'propose',jsonb_build_object('creator_id',cx,'reason','Video scope'))->>'id')::uuid;
 perform creator_team_action(c,rid,'select',jsonb_build_object('proposal_id',px));
 -- Staff may add another candidate while preparing the team, before a quote exists.
 py:=(request_commerce_action(s,rid,'propose',jsonb_build_object('creator_id',cy,'reason','Photo scope'))->>'id')::uuid;
 perform creator_team_action(c,rid,'select',jsonb_build_object('proposal_id',py));
 if (select count(*) from request_creator_selections where request_id=rid)<>2 then raise exception 'Multiple Creator selection lost'; end if;
 denied:=false; begin perform creator_team_action(s,rid,'select',jsonb_build_object('proposal_id',py)); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Staff impersonates customer team selection'; end if;
 denied:=false; begin perform creator_team_action(s,rid,'invite',jsonb_build_object('proposal_id',px,'deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'work_scope','Video','response_minutes',16)); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Reservation exceeds 15 minutes'; end if;
 ax:=(creator_team_action(s,rid,'invite',jsonb_build_object('proposal_id',px,'deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'work_scope','Video','response_minutes',5))->>'id')::uuid;
 ay:=(creator_team_action(s,rid,'invite',jsonb_build_object('proposal_id',py,'deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'work_scope','Photo','response_minutes',15))->>'id')::uuid;
 denied:=false; begin perform creator_team_action(s,rid,'accept',jsonb_build_object('assignment_id',ax)); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Staff confirms Creator assignment'; end if;
 perform creator_team_action(x,rid,'accept',jsonb_build_object('assignment_id',ax));
 if creator_team_action(x,rid,'accept',jsonb_build_object('assignment_id',ax))->>'id'<>ax::text then raise exception 'Accept is not idempotent'; end if;
 denied:=false; begin perform request_commerce_action(s,rid,'quote_save',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('service_id',svc,'description','Team work','quantity',1,'unit_price',1000)),'valid_until',(now() at time zone 'Asia/Ho_Chi_Minh')::date+10,'revision_policy','Agreed scope','deposit_percent',30)); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Quote bypasses second Creator confirmation'; end if;
 perform set_config('request.jwt.claim.sub',xa::text,true); execute 'set local role authenticated';
 if exists(select 1 from conversations where id=conv) or exists(select 1 from conversation_messages where conversation_id=conv) then raise exception 'Creator chat opens before customer contract'; end if;
 execute 'reset role';
 perform creator_team_action(y,rid,'accept',jsonb_build_object('assignment_id',ay));
 q:=(request_commerce_action(s,rid,'quote_save',jsonb_build_object('items',jsonb_build_array(jsonb_build_object('service_id',svc,'description','Team work','quantity',1,'unit_price',1000)),'valid_until',(now() at time zone 'Asia/Ho_Chi_Minh')::date+10,'revision_policy','Agreed scope','deposit_percent',30))->>'id')::uuid;
 if jsonb_array_length((select team_snapshot from quotations where id=q))<>2 then raise exception 'Quote did not retain full team'; end if;
 perform request_commerce_action(s,rid,'quote_send',jsonb_build_object('quote_id',q));
 denied:=false; begin update quotations set team_snapshot='[]' where id=q; exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Published team snapshot is mutable'; end if;
 oid:=(request_commerce_action(c,rid,'quote_accept',jsonb_build_object('quote_id',q))->>'order_id')::uuid;
