 contract:=(order_action(s,oid,'contract_save',jsonb_build_object('title','Test terms','content','Rollback only terms','valid_until',(now() at time zone 'Asia/Ho_Chi_Minh')::date+10))->>'id')::uuid;
 perform order_action(s,oid,'contract_send',jsonb_build_object('contract_id',contract));
 perform order_action(c,oid,'contract_acknowledge',jsonb_build_object('contract_id',contract,'content_hash',(select content_hash from order_contracts where id=contract),'acknowledge',true));
 if jsonb_array_length((select team_snapshot from order_contracts where id=contract))<>2 or (select count(*) from conversations where request_id=rid)<>1 then raise exception 'Contract roster or single conversation failed'; end if;
 perform request_action(c,rid,'message','{"content":"Private financial follow-up","audience":"CUSTOMER_STAFF"}');
 if exists(select 1 from notifications where user_id=x and message='Private financial follow-up') then raise exception 'Private text leaked in Creator notification'; end if;
 if (select last_message_preview from conversations where id=conv) like '%financial%' then raise exception 'Private preview leaked'; end if;
 perform request_action(x,rid,'message','{"content":"Shared team update"}');
 denied:=false; begin perform request_action(x,rid,'message','{"content":"Impersonate private","audience":"CUSTOMER_STAFF"}'); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Creator writes private commercial channel'; end if;
 perform set_config('request.jwt.claim.sub',xa::text,true); execute 'set local role authenticated';
 if not exists(select 1 from conversation_messages where conversation_id=conv and content='Shared team update') or exists(select 1 from conversation_messages where conversation_id=conv and (audience='CUSTOMER_STAFF' or kind in ('QUOTE','CONTRACT','PAYMENT'))) then raise exception 'Creator message RLS leaks private history or hides shared messages'; end if;
 if exists(select 1 from quotations where id=q) or exists(select 1 from order_contracts where id=contract) or exists(select 1 from orders where id=oid) then raise exception 'Creator can read customer finances'; end if;
 execute 'reset role';
 update profiles set active=false where id=x;
 perform set_config('request.jwt.claim.sub',xa::text,true); execute 'set local role authenticated';
 if exists(select 1 from conversation_messages where conversation_id=conv) then raise exception 'Suspended Creator retains chat access'; end if;
 execute 'reset role'; update profiles set active=true where id=x;
 r2:=(request_action(c,null,'create',jsonb_build_object('service_id',svc,'title','Other team','brief','Test only','idempotency_key',gen_random_uuid()))->>'id')::uuid;
 perform request_action(s2,r2,'claim','{}'); perform request_action(s2,r2,'status','{"status":"CONSULTING"}');
 p2:=(request_commerce_action(s2,r2,'propose',jsonb_build_object('creator_id',cx,'reason','Other project'))->>'id')::uuid;
 perform creator_team_action(c,r2,'select',jsonb_build_object('proposal_id',p2));
 denied:=false; begin perform creator_team_action(s2,r2,'invite',jsonb_build_object('proposal_id',p2,'deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'work_scope','Another video')); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Creator accepted on two active projects'; end if;
 if (select status from creator_assignments where id=ax)<>'ACCEPTED' then raise exception 'Original reservation released too early'; end if;
 pz:=(request_commerce_action(s2,r2,'propose',jsonb_build_object('creator_id',cz,'reason','Expiry test'))->>'id')::uuid;
 perform creator_team_action(c,r2,'select',jsonb_build_object('proposal_id',pz));
 az:=(creator_team_action(s2,r2,'invite',jsonb_build_object('proposal_id',pz,'work_scope','Expiry scope','deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'response_minutes',5))->>'id')::uuid;
 update creator_assignments set invited_at=clock_timestamp()-interval '10 minutes',expires_at=clock_timestamp()-interval '1 minute' where id=az;
 denied:=false; begin perform creator_team_action(z,r2,'accept',jsonb_build_object('assignment_id',az)); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Expired reservation accepted'; end if;
 perform creator_team_action(s2,r2,'invite',jsonb_build_object('proposal_id',pz,'work_scope','Expiry scope','deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'response_minutes',5));
 perform creator_team_action(z,r2,'decline',jsonb_build_object('assignment_id',az,'reason','Cannot meet deadline'));
