 if not exists(select 1 from audit_logs where entity_id=az and new_value->>'response_note'='Cannot meet deadline') then raise exception 'Assignment response history was lost'; end if;
 perform creator_team_action(s2,r2,'invite',jsonb_build_object('proposal_id',pz,'work_scope','Expiry scope','deadline',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'response_minutes',5));
 perform request_action(c,r2,'cancel','{"reason":"Withdraw an unclosed consultation only"}');
 if (select status from creator_assignments where id=az)<>'RELEASED' or (select status from creator_assignments where id=ax)<>'ACCEPTED' then raise exception 'Cancelling an unclosed request did not release only its own reservation'; end if;
