 perform order_payment_action(c,oid,'report',jsonb_build_object('payment_id',pay,'transfer_note','ROLLBACK ONLY'));
 perform order_payment_action(a,oid,'confirm',jsonb_build_object('payment_id',pay,'verified',true,'received_amount',300,'bank_transaction_reference',gen_random_uuid(),'received_at',now(),'reason','ROLLBACK ONLY'));
 perform set_config('request.jwt.claim.sub',xa::text,true); execute 'set local role authenticated';
 if exists(select 1 from conversation_messages where conversation_id=conv and (event_data->>'event') like 'PAYMENT_%') then raise exception 'Financial SYSTEM events leaked to Creator'; end if;
 execute 'reset role';
 prod_id:=(order_production_action(s,oid,'create','{}')->>'id')::uuid;
 if (select count(*) from project_team_members tm where tm.project_id=prod_id)<>2 then raise exception 'Production does not contain the whole team'; end if;
 perform order_production_action(s,oid,'milestone_save',jsonb_build_object('title','Test milestone','description','Test only','due_date',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'display_order',0,'idempotency_key',gen_random_uuid()));
 perform order_production_action(s,oid,'status','{"status":"READY","reason":"Rollback only"}');
 perform order_production_action(s,oid,'status','{"status":"IN_PROGRESS","reason":"Rollback only"}');
 perform creator_team_action(x,rid,'progress',jsonb_build_object('assignment_id',ax,'progress',100,'content','Reported externally; stored progress'));
 if (select status from creator_assignments where id=ax)<>'ACCEPTED' or not exists(select 1 from creator_progress_updates where assignment_id=ax and progress=100) then raise exception '100 percent progress freed Creator or failed to persist'; end if;
 denied:=false; begin perform creator_team_action(y,rid,'progress',jsonb_build_object('assignment_id',ax,'progress',100,'content','Other Creator progress')); exception when raise_exception then denied:=true; end;
 if not denied then raise exception 'Creator updates another assignment'; end if;
 if has_function_privilege('authenticated','creator_team_action(uuid,uuid,text,jsonb)','EXECUTE') or has_function_privilege('service_role','legacy_request_action_027(uuid,uuid,text,jsonb)','EXECUTE') or has_table_privilege('authenticated','creator_assignments','UPDATE') then raise exception 'Untrusted direct Creator assignment access'; end if;
 -- Multi-Creator review/final delivery retains the same workspace and only
