 path_x:=oid::text||'/'||gen_random_uuid()::text||'.pdf';path_y:=oid::text||'/'||gen_random_uuid()::text||'.pdf';
 insert into storage.objects(bucket_id,name,metadata) values('order-deliverables',path_x,'{"size":100,"mimetype":"application/pdf"}'),('order-deliverables',path_y,'{"size":100,"mimetype":"application/pdf"}');
 upload_input:=jsonb_build_object('assignment_id',ax,'kind','REVIEW','title','Video review','confirmed',true,'file_name','review.pdf','path',path_x,'type','application/pdf','size',100);
 denied:=false;begin perform order_delivery_action(y,oid,'upload',upload_input);exception when raise_exception then denied:=true;end;if not denied then raise exception 'Creator uploads other assignment';end if;
 denied:=false;begin perform order_delivery_action(x,oid,'upload',upload_input||'{"confirmed":false}');exception when raise_exception then denied:=true;end;if not denied then raise exception 'Review lacks watermark declaration';end if;
 file_x:=(order_delivery_action(x,oid,'upload',upload_input)->>'submission_id')::uuid;
 file_y:=(order_delivery_action(y,oid,'upload',upload_input||jsonb_build_object('assignment_id',ay,'title','Photo review','path',path_y))->>'submission_id')::uuid;
 denied:=false;begin perform order_delivery_action(s,oid,'send_review',jsonb_build_object('submission_ids',jsonb_build_array(file_x,file_y),'note','Mốc chưa hoàn thành'));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Review skips incomplete milestones';end if;
 perform order_production_action(s,oid,'milestone_status',jsonb_build_object('milestone_id',(select id from project_milestones where project_id=prod_id limit 1),'status','IN_PROGRESS','reason','Review test'));
 perform order_production_action(s,oid,'milestone_status',jsonb_build_object('milestone_id',(select id from project_milestones where project_id=prod_id limit 1),'status','COMPLETED','reason','Review test completed'));
 denied:=false;begin perform order_delivery_action(s,oid,'send_review',jsonb_build_object('submission_ids',jsonb_build_array(file_x),'note','Missing team member'));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Review omits a Creator';end if;
 round_id:=(order_delivery_action(s,oid,'send_review',jsonb_build_object('submission_ids',jsonb_build_array(file_x,file_y),'note','Review full team'))->>'round_id')::uuid;
 denied:=false;begin perform order_delivery_action(a,oid,'accept_review',jsonb_build_object('round_id',round_id,'confirmed',true));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Admin impersonates customer review acceptance';end if;
