 round_id:=(order_delivery_action(s,oid,'send_review',jsonb_build_object('submission_ids',jsonb_build_array(file_x,file_y),'note','Reviewed agreed scope again'))->>'round_id')::uuid;
 perform order_delivery_action(c,oid,'accept_review',jsonb_build_object('round_id',round_id,'confirmed',true));
 perform order_delivery_action(c,oid,'accept_review',jsonb_build_object('round_id',round_id,'confirmed',true));
 perform pg_temp.verify_service_chat(a,c,s,x,rid,conv);
 if (select count(*) from order_review_rounds where order_id=oid)<>2 or (select status from orders where id=oid)<>'WAITING_ACCEPTANCE' then raise exception 'Review history/acceptance missing';end if;
 path_x:=oid::text||'/'||gen_random_uuid()::text||'.pdf';path_y:=oid::text||'/'||gen_random_uuid()::text||'.pdf';
 insert into storage.objects(bucket_id,name,metadata) values('order-deliverables',path_x,'{"size":100,"mimetype":"application/pdf"}'),('order-deliverables',path_y,'{"size":100,"mimetype":"application/pdf"}');
 upload_input:=jsonb_build_object('assignment_id',ax,'kind','FINAL','final_of',file_x,'title','Final video','confirmed',true,'file_name','final.pdf','path',path_x,'type','application/pdf','size',100);
 denied:=false;begin perform order_delivery_action(x,oid,'upload',upload_input);exception when raise_exception then denied:=true;end;if not denied then raise exception 'Final released before full funds';end if;
 remainder:=(order_payment_action(s,oid,'create',jsonb_build_object('kind','REMAINING','due_date',(now() at time zone 'Asia/Ho_Chi_Minh')::date+7,'idempotency_key',gen_random_uuid()))->>'id')::uuid;
 perform order_payment_action(c,oid,'report',jsonb_build_object('payment_id',remainder,'transfer_note','Synthetic remainder'));
 perform order_payment_action(s,oid,'confirm',jsonb_build_object('payment_id',remainder,'verified',true,'received_amount',700,'bank_transaction_reference',gen_random_uuid(),'received_at',now(),'reason','Actual evidence rollback only'));
 denied:=false;begin perform order_delivery_action(x,oid,'upload',upload_input);exception when raise_exception then denied:=true;end;if not denied then raise exception 'Final released without Staff full-funds confirmation';end if;
 perform confirm_order_final_funds(s,oid,'{"verified":true,"note":"Full funds checked rollback only"}');
 final_x:=(order_delivery_action(x,oid,'upload',upload_input)->>'submission_id')::uuid;
 if (select status from orders where id=oid)='COMPLETED' or (select status from creator_assignments where id=ax)<>'ACCEPTED' then raise exception 'Partial final delivery completes project/frees Creator';end if;
 denied:=false;begin perform order_feedback_action(c,oid,'review',jsonb_build_object('show_name',false,'notice_version','EXCERPT_V1','rating',5,'content','Too soon','creators','[]'::jsonb));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Feedback opens before full-team final delivery';end if;
 final_y:=(order_delivery_action(y,oid,'upload',upload_input||jsonb_build_object('assignment_id',ay,'final_of',file_y,'title','Final photo','path',path_y))->>'submission_id')::uuid;
 if (select status from orders where id=oid)<>'COMPLETED' or (select production_status from projects where id=prod_id)<>'COMPLETED' or (select count(*) from creator_assignments where request_id=rid and status='COMPLETED')<>2 then raise exception 'Complete team delivery did not finish/release whole project';end if;
 perform pg_temp.verify_completed_feedback(a,c,s,x,oid,cx,cy);
