 if exists(select 1 from storage.objects where bucket_id='order-deliverables') then raise exception 'Client bypasses signed download through storage';end if;
 execute 'reset role';
 if has_function_privilege('authenticated','order_delivery_action(uuid,uuid,text,jsonb)','execute') or has_function_privilege('authenticated','is_delivery_reader(uuid,uuid)','execute') or has_table_privilege('authenticated','production_submissions','insert') then raise exception 'Untrusted delivery write/bypass exposed';end if;
end $$;
